templates.content:
body {
  font-family: system-ui, sans-serif;
  line-height: 1.5;
  margin: 0;
}

main {
  max-width: 42rem;
  margin: 3rem auto;
  padding: 0 1rem;
}

.callout {
  padding: 1rem;
  border-left: 4px solid #4f46e5;
  background: #eef2ff;
}

const button = document.querySelector("#message-button");

button.addEventListener("click", () => {
  button.textContent = "JavaScript changed this text";
});
